import fitz, os, re, shutil

base = "/Users/mac/.cursor/projects/Users-mac-Desktop-CHcode/attachments/4507ce63-e7a5-481c-a486-a3f6515acd24"
out_dir = "/Users/mac/Desktop/CHcode/tmp/pdf_edit_out"
preview = "/Users/mac/Desktop/CHcode/tmp/pdf_edit_preview"
os.makedirs(out_dir, exist_ok=True)

FONTFILE = "/System/Library/Fonts/STHeiti Light.ttc"
NEW_CHECK = "2026.11.01"
NEW_REPORT = "2026.11.02"

def rgb_of(color_int):
    return ((color_int >> 16) & 255) / 255, ((color_int >> 8) & 255) / 255, (color_int & 255) / 255

def span_at(page, rect):
    for b in page.get_text('dict')['blocks']:
        if b.get('type') != 0:
            continue
        for line in b.get('lines', []):
            for s in line.get('spans', []):
                if fitz.Rect(s['bbox']).intersects(rect):
                    return s
    return None

def near_label(page, rect, label, max_dy=6):
    for lr in page.search_for(label):
        if abs(lr.y0 - rect.y0) <= max_dy and rect.x0 >= lr.x0 - 10:
            return True
    return False

def expand_with_same_line(page, rect, extra_needles):
    r = fitz.Rect(rect)
    for needle in extra_needles:
        for tr in page.search_for(needle):
            if abs(tr.y0 - rect.y0) < 2 and tr.x0 >= rect.x0 - 1:
                r |= tr
    return r

def process(name):
    src = os.path.join(base, name)
    doc = fitz.open(src)
    inserts = []  # (page_index, point, text, fontsize, color)
    stats = {'remove_yangcai': 0, 'remove_label': 0, 'check': 0, 'report': 0}

    for pi, page in enumerate(doc):
        redacts = []  # list of rects to white out

        # --- remove 阳采集团有限公司 ---
        yangcai_rects = list(page.search_for('阳采集团有限公司'))
        for r in yangcai_rects:
            redacts.append(fitz.Rect(r))
            stats['remove_yangcai'] += 1

        if yangcai_rects:
            # remove matching 单位名称 label (+ colon)
            for r in page.search_for('单位名称'):
                rr = fitz.Rect(r)
                for c in list(page.search_for(':')) + list(page.search_for('：')):
                    if abs(c.y0 - rr.y0) < 3 and rr.x1 - 2 <= c.x0 <= rr.x1 + 14:
                        rr |= c
                redacts.append(rr)
                stats['remove_label'] += 1

        # --- replacements: collect (old_rect, new_text) ---
        replacements = []

        # 检查日期 date-only
        for r in page.search_for('2025-05-29'):
            if near_label(page, r, '检查日期') and r.width < 70:
                replacements.append((fitz.Rect(r), NEW_CHECK, 'check'))

        # 检测时间 full timestamps
        detect_pats = [
            '2025-05-29 13:03:28', '2025-05-29 13:15:23', '2025-05-29 13:07:10',
        ]
        for pat in detect_pats:
            for r in page.search_for(pat):
                if near_label(page, r, '检测时间'):
                    replacements.append((fitz.Rect(r), NEW_CHECK, 'check'))

        # 报告时间
        report_pats = [
            '2025-05-30 15:08:03', '2025-05-29 14:10:44', '2025-05-29 14:39:46',
        ]
        for pat in report_pats:
            for r in page.search_for(pat):
                if near_label(page, r, '报告时间'):
                    replacements.append((fitz.Rect(r), NEW_REPORT, 'report'))

        # Fallback: any remaining timestamp classified by label
        for r in page.search_for('2025-05-'):
            # skip partial - search_for may not work with partial
            pass
        # broader: find words matching date pattern via words
        for w in page.get_text('words'):
            word = w[4]
            rect = fitz.Rect(w[:4])
            if re.fullmatch(r'2025-05-\d{2}', word):
                if near_label(page, rect, '检查日期'):
                    replacements.append((rect, NEW_CHECK, 'check'))
                elif near_label(page, rect, '检测时间'):
                    # date part of detection time — expand with time
                    rr = expand_with_same_line(page, rect, [x[4] for x in page.get_text('words') if abs(x[1]-w[1])<2 and re.search(r'\d{2}:\d{2}', x[4])])
                    # if time on same line as separate word
                    for x in page.get_text('words'):
                        if abs(x[1]-w[1])<2 and re.fullmatch(r'\d{2}:\d{2}:\d{2}', x[4]) and x[0] > w[0]:
                            rr |= fitz.Rect(x[:4])
                    if near_label(page, rect, '检测时间'):
                        replacements.append((rr, NEW_CHECK, 'check'))
                    elif near_label(page, rect, '报告时间'):
                        replacements.append((rr, NEW_REPORT, 'report'))

        # 日期：2025年05月29日 → use dotted form to avoid CJK in redaction font
        for r in page.search_for('2025年05月29日'):
            replacements.append((fitz.Rect(r), NEW_CHECK, 'check'))
        for r in page.search_for('本次（2025-05-29）'):
            replacements.append((fitz.Rect(r), f'本次（{NEW_CHECK}）', 'check'))

        # PDF24 体检时间
        for r in page.search_for('2023/3/3'):
            if near_label(page, r, '体检时间'):
                rr = expand_with_same_line(page, r, ['8:09:05'])
                for x in page.get_text('words'):
                    if abs(x[1]-r.y0)<2 and ('8:09' in x[4] or x[4]=='8:09:05'):
                        rr |= fitz.Rect(x[:4])
                replacements.append((rr, NEW_CHECK, 'check'))

        # Deduplicate replacements by overlapping rects (keep first)
        kept = []
        for rect, new, kind in replacements:
            if any(rect.intersects(k[0]) for k in kept):
                continue
            kept.append((rect, new, kind))

        for rect, new, kind in kept:
            style = span_at(page, rect)
            fs = style['size'] if style else 8
            color = rgb_of(style['color']) if style else (0, 0, 0)
            redacts.append(fitz.Rect(rect))
            # insert slightly above baseline: use rect.bl + small offset
            inserts.append((pi, fitz.Point(rect.x0, rect.y1 - fs * 0.15), new, fs, color, kind))
            stats[kind if kind in stats else 'check'] += 1
            if kind == 'check':
                pass
            elif kind == 'report':
                pass

        for r in redacts:
            page.add_redact_annot(r, fill=(1, 1, 1))
        if redacts:
            page.apply_redactions(images=fitz.PDF_REDACT_IMAGE_NONE)

    # After all pages redacted, insert texts
    for pi, point, text, fs, color, kind in inserts:
        page = doc[pi]
        # Use fontfile for CJK-safe insertion (ASCII also fine)
        page.insert_text(
            point,
            text,
            fontsize=fs,
            fontfile=FONTFILE,
            fontname='heiti',
            color=color,
        )
        stats[kind] = stats.get(kind, 0)  # already counted

    out_path = os.path.join(out_dir, name)
    tmp = out_path + '.tmp.pdf'
    doc.save(tmp, garbage=4, deflate=True)
    doc.close()
    os.replace(tmp, out_path)
    return stats

for name in ['__________-84064824_.pdf', '__________-84064825_.pdf', '__________-84064826_.pdf']:
