os.makedirs(out_dir, exist_ok=True)
os.makedirs(desktop_out, exist_ok=True)

FONTFILE = "/System/Library/Fonts/STHeiti Light.ttc"
NEW_CHECK = "2026.11.01"
NEW_REPORT = "2026.11.02"
BLUE = (0.902, 0.9255, 0.9608)
WHITE = (1, 1, 1)

def rgb_of(color_int):
    return ((color_int >> 16) & 255) / 255, ((color_int >> 8) & 255) / 255, (color_int & 255) / 255

def span_at(page, rect):
    for b in page.get_text('dict')['blocks']:
        if b.get('type') != 0:
            continue
        for line in b.get('lines', []):
            for s in line.get('spans', []):
                if fitz.Rect(s['bbox']).intersects(rect):
                    return s
    return None

def near_label(page, rect, label, max_dy=6):
    for lr in page.search_for(label):
        if abs(lr.y0 - rect.y0) <= max_dy and rect.x0 >= lr.x0 - 10:
            return True
    return False

def banner_fill(page, rect):
    """If rect sits on light-blue banner drawing, use that fill."""
    for d in page.get_drawings():
        fill = d.get('fill')
        if not fill or len(fill) < 3:
            continue
        # light blue-ish
        if fill[2] > fill[0] and fill[0] > 0.7:
            dr = d.get('rect')
            if dr and fitz.Rect(dr).intersects(rect):
                return tuple(fill[:3])
    return WHITE

def union_label_colon(page, label_rect):
    rr = fitz.Rect(label_rect)
    for c in list(page.search_for(':')) + list(page.search_for('：')):
        if abs(c.y0 - rr.y0) < 3 and rr.x1 - 2 <= c.x0 <= rr.x1 + 14:
            rr |= c
    return rr

def process(name):
    src = os.path.join(base, name)
    doc = fitz.open(src)
    inserts = []
    stats = {'yangcai': 0, 'label': 0, 'check': 0, 'report': 0}

    for pi, page in enumerate(doc):
        redacts = []  # (rect, fill)
        replacements = []

        yangcai_rects = list(page.search_for('阳采集团有限公司'))
        for r in yangcai_rects:
            redacts.append((fitz.Rect(r), WHITE))
            stats['yangcai'] += 1

        if yangcai_rects:
            # one unified label redact (avoid 4 char hits)
            labels = list(page.search_for('单位名称'))
            if labels:
                rr = labels[0]
                for r in labels[1:]:
                    if abs(r.y0 - rr.y0) < 3:
                        rr |= r
                rr = union_label_colon(page, rr)
                redacts.append((rr, WHITE))
                stats['label'] += 1

        # 检查日期
        for r in page.search_for('2025-05-29'):
            if near_label(page, r, '检查日期') and r.width < 70:
                replacements.append((fitz.Rect(r), NEW_CHECK, 'check'))

        for pat in ['2025-05-29 13:03:28', '2025-05-29 13:15:23', '2025-05-29 13:07:10']:
            for r in page.search_for(pat):
                if near_label(page, r, '检测时间'):
                    replacements.append((fitz.Rect(r), NEW_CHECK, 'check'))

        for pat in ['2025-05-30 15:08:03', '2025-05-29 14:10:44', '2025-05-29 14:39:46']:
            for r in page.search_for(pat):
                if near_label(page, r, '报告时间'):
                    replacements.append((fitz.Rect(r), NEW_REPORT, 'report'))

        # word-level fallback for split date/time
        for w in page.get_text('words'):
            word = w[4]
            rect = fitz.Rect(w[:4])
            if not re.fullmatch(r'2025-05-\d{2}', word):
                continue
            if near_label(page, rect, '检查日期'):
                replacements.append((rect, NEW_CHECK, 'check'))
            elif near_label(page, rect, '检测时间') or near_label(page, rect, '报告时间'):
                rr = fitz.Rect(rect)
                for x in page.get_text('words'):
                    if abs(x[1] - w[1]) < 2 and re.fullmatch(r'\d{2}:\d{2}:\d{2}', x[4]) and x[0] > w[0]:
                        rr |= fitz.Rect(x[:4])
                if near_label(page, rect, '检测时间'):
                    replacements.append((rr, NEW_CHECK, 'check'))
                else:
                    replacements.append((rr, NEW_REPORT, 'report'))

        for r in page.search_for('2025年05月29日'):
            replacements.append((fitz.Rect(r), NEW_CHECK, 'check'))
        for r in page.search_for('本次（2025-05-29）'):
            replacements.append((fitz.Rect(r), f'本次（{NEW_CHECK}）', 'check'))

        for r in page.search_for('2023/3/3'):
            if near_label(page, r, '体检时间'):
                rr = fitz.Rect(r)
                for x in page.get_text('words'):
                    if abs(x[1] - r.y0) < 2 and ('8:09' in x[4]):
                        rr |= fitz.Rect(x[:4])
                replacements.append((rr, NEW_CHECK, 'check'))

        kept = []
        for rect, new, kind in replacements:
            if any(rect.intersects(k[0]) for k in kept):
                continue
            kept.append((rect, new, kind))

        for rect, new, kind in kept:
            style = span_at(page, rect)
            fs = style['size'] if style else 8
            color = rgb_of(style['color']) if style else (0, 0, 0)
            fill = banner_fill(page, rect)
            redacts.append((fitz.Rect(rect), fill))
            inserts.append((pi, fitz.Point(rect.x0, rect.y1 - fs * 0.15), new, fs, color))
            stats[kind] += 1

        for r, fill in redacts:
            page.add_redact_annot(r, fill=fill)
        if redacts:
            page.apply_redactions(images=fitz.PDF_REDACT_IMAGE_NONE)

    for pi, point, text, fs, color in inserts:
        doc[pi].insert_text(point, text, fontsize=fs, fontfile=FONTFILE, fontname='heiti', color=color)

    out_path = os.path.join(out_dir, name)
    tmp = out_path + '.tmp.pdf'
    doc.save(tmp, garbage=4, deflate=True)
    doc.close()
    os.replace(tmp, out_path)
    return stats

# Friendly output names based on content
friendly = {
    '__________-84064824_.pdf': '体检报告_美年_已改.pdf',
