doc = fitz.open(os.path.join(out_dir, '__________-84064826_.pdf'))
pix = doc[0].get_pixmap(matrix=fitz.Matrix(2.2,2.2), clip=fitz.Rect(280,560,500,710))
pix.save(f'{preview}/v3_cover26.png')
pix = doc[8].get_pixmap(matrix=fitz.Matrix(2.5,2.5), clip=fitz.Rect(150,650,400,690))
pix.save(f'{preview}/v3_p8_banner.png')
print('previews saved')

# final verify
for name in friendly:
    doc = fitz.open(os.path.join(out_dir, name))
    full = '\n'.join(p.get_text() for p in doc)
    assert '阳采' not in full
    assert '2025-05' not in full
