# Extract usable font buffers from a source PDF
def extract_fonts(doc):
    """Return dict name_key -> (fontbuffer, fontname_for_insert)."""
    fonts = {}
    seen = set()
    for pi in range(doc.page_count):
        for item in doc.get_page_fonts(pi):
            xref = item[0]
            if xref in seen:
                continue
            seen.add(xref)
            try:
                name, ext, typ, content = doc.extract_font(xref)
            except Exception:
                continue
            if not content:
                continue
            key = name.split('+')[-1]  # FZLTHJW--GB1-0 / LiberationSans / ArialRegular
            # keep largest buffer for same family (more glyphs)
            if key not in fonts or len(content) > len(fonts[key][0]):
                fonts[key] = (content, name, ext)
    return fonts

def rgb_of(c):
    return ((c >> 16) & 255) / 255, ((c >> 8) & 255) / 255, (c & 255) / 255

def span_at(page, rect):
    best = None
    best_area = 0
    for b in page.get_text('dict')['blocks']:
        if b.get('type') != 0:
            continue
        for line in b.get('lines', []):
            for s in line.get('spans', []):
                sb = fitz.Rect(s['bbox'])
                inter = sb & rect
                if inter.is_empty:
                    continue
                area = inter.width * inter.height
                if area > best_area:
                    best_area = area
                    best = s
    return best

def near_label(page, rect, label, max_dy=6):
    for lr in page.search_for(label):
        if abs(lr.y0 - rect.y0) <= max_dy and rect.x0 >= lr.x0 - 10:
            return True
    return False

def banner_fill(page, rect):
    for d in page.get_drawings():
        fill = d.get('fill')
        if not fill or len(fill) < 3:
            continue
        if fill[2] > fill[0] and fill[0] > 0.7:
            dr = d.get('rect')
            if dr and fitz.Rect(dr).intersects(rect):
                return tuple(fill[:3])
    return WHITE

def pick_fontbuffer(fonts, span_font):
    """Match span font name to extracted buffer."""
    if not span_font:
        # prefer LiberationSans then Arial
        for k in ('LiberationSans', 'ArialRegular', 'Arial'):
            if k in fonts:
                return fonts[k]
        return next(iter(fonts.values()))
    sf = span_font.split('+')[-1]
    if sf in fonts:
        return fonts[sf]
    # fuzzy
    for k, v in fonts.items():
        if k in sf or sf in k:
            return v
    if 'Arial' in sf or 'Liberation' in sf or 'Sans' in sf:
        for k in ('LiberationSans', 'ArialRegular'):
            if k in fonts:
                return fonts[k]
    for k in fonts:
        if 'FZLTH' in k or 'GB1' in k:
            return fonts[k]
    return next(iter(fonts.values()))

