            parts = sorted(parts, key=lambda x: x['origin'].x)
            # expect 2025,年,05,月,29,日
            texts = [p['text'] for p in parts]
            if texts[:6] == ['2025', '年', '05', '月', '29', '日'] or (len(parts) >= 6 and parts[0]['text'] == '2025'):
                seq = parts[:6]
                if [p['text'] for p in seq] != ['2025', '年', '05', '月', '29', '日']:
                    # try find contiguous
                    continue
                rect = seq[0]['bbox']
                for p in seq[1:]:
                    rect |= p['bbox']
                jobs.append({'rect': rect, 'fill': WHITE, 'new': NEW_CHECK,
                             'origin': seq[0]['origin'], 'size': seq[0]['size'], 'color': seq[0]['color'],
                             'fontfile': LIBERATION})
                stats['check'] += 1

        kept = []
        for job in jobs:
            if any(job['rect'].intersects(k['rect']) for k in kept):
                continue
            kept.append(job)

        for job in kept:
            page.add_redact_annot(job['rect'], fill=job['fill'])
        if kept:
            page.apply_redactions(images=fitz.PDF_REDACT_IMAGE_NONE)

        for job in kept:
            if not job.get('new'):
                continue
            ff = job['fontfile']
            if ff == ARIAL:
                fname = 'FArial'
            elif ff == LIBERATION_BOLD:
                fname = 'FLiberB'
            else:
                fname = 'FLiber'
            page.insert_font(fontname=fname, fontfile=ff)
            rc = page.insert_text(job['origin'], job['new'], fontsize=job['size'],
                                  fontname=fname, fontfile=ff, color=job['color'])
            print(f"  p{pi} {job['new']!r} size={job['size']:.2f} rc={rc} {os.path.basename(ff)}")

    out = os.path.join(out_dir, name)
    tmp = out + '.tmp.pdf'
    doc.save(tmp, garbage=4, deflate=True)
    doc.close()
    os.replace(tmp, out)
    return stats

